// The three top types: same values, different permissions
Object? a = 42;
dynamic b = 42;
void c = 42;             // assigning to void is fine

// a.isEven;             // ❌ Object has no isEven — narrow first
if (a is int) print(a.isEven);   // ✅ promoted to int

b.isEven;                // ✅ compiles — resolved at runtime
b.isEvne();              // ✅ compiles too — NoSuchMethodError in production

// print(c);             // ❌ "This expression has type 'void' and can't be used"

// The bottom type
Never fail(String message) => throw StateError(message);

int parsePort(String raw) {
  final n = int.tryParse(raw);
  if (n == null) fail('bad port: $raw');   // Never ends the flow here
  return n;                                 // n is a non-null int
}

final int port = fail('no config');   // ✅ Never is a subtype of int
// print(port);                       // analyzer: Dead code

// Null is not the bottom
print(null is Object);          // false
print(null is Object?);         // true
print(<Never>[].runtimeType);   // List<Never> — provably always empty

// T? is T | Null
int? maybe = null;              // int or Null
Never? nothing = null;          // Never? IS Null — only null fits

// ❌ void — the call is just another statement, flow continues past it
void failVoid(String m) => throw StateError(m);

int lengthBad(String? s) {
  if (s == null) failVoid('null input');
  return s.length;      // ❌ receiver can be 'null' — no promotion
}

// ✅ Never — the call ends the flow
Never failNever(String m) => throw StateError(m);

int lengthGood(String? s) {
  if (s == null) failNever('null input');
  return s.length;      // ✅ s is String for the rest of the body
}

// Satisfies the "body might complete normally" check
String label(int code) {
  switch (code) {
    case 200: return 'ok';
    case 404: return 'missing';
    default: failNever('unhandled code $code');
  }
}

// Never is the bottom type — assignable in any context
final Duration timeout = failNever('not configured');

// throw is an expression of type Never
String required(String? v) => v ?? (throw ArgumentError.notNull('v'));

// async: the type must be Future<Never>, and only await ends the flow
Future<Never> failAsync(String m) async => throw StateError(m);

Future<int> lengthAsyncBad(String? s) async {
  if (s == null) failAsync('null');        // ❌ not awaited — flow continues
  return s.length;                          // ❌ still nullable here
}

Future<int> lengthAsyncGood(String? s) async {
  if (s == null) await failAsync('null');  // ✅ await makes the rest unreachable
  return s.length;
}

