// ❌ narrowing == breaks every collection that holds the value
class Money {
  final int cents;
  const Money(this.cents);
  @override
  bool operator ==(covariant Money other) => other.cents == cents;
  @override
  int get hashCode => cents.hashCode;
}

// ✅ keep Object in the signature and narrow inside the body
class Price {
  final int cents;
  const Price(this.cents);

  @override
  bool operator ==(Object other) =>
      identical(this, other) || other is Price && other.cents == cents;

  @override
  int get hashCode => cents.hashCode;
}

