// ❌ raw bound == Comparable<dynamic>: compareTo takes anything at all
T maxRaw<T extends Comparable>(List<T> xs) =>
    xs.reduce((a, b) => a.compareTo(b) >= 0 ? a : b);

// maxRaw<Object>([Duration.zero, 'later']);
//   compiles; TypeError out of Duration.compareTo at runtime

// ✅ F-bound: T must be comparable to its own kind
T maxSelf<T extends Comparable<T>>(List<T> xs) =>
    xs.reduce((a, b) => a.compareTo(b) >= 0 ? a : b);

class Money implements Comparable<Money> {
  final int cents;
  const Money(this.cents);
  @override
  int compareTo(Money other) => cents.compareTo(other.cents);
}

final richest = maxSelf([const Money(5), const Money(9)]);   // ✅

// maxSelf([3, 1, 9]);
//   ❌ 'int' doesn't conform to the bound 'Comparable<int>'
//      int implements Comparable<num>, and Comparable<num> is NOT
//      a subtype of Comparable<int> — covariance only goes the other way

// ✅ the bound that covers the numeric tower as well
T maxAny<T extends Comparable<Object>>(List<T> xs) =>
    xs.reduce((a, b) => a.compareTo(b) >= 0 ? a : b);

final biggest = maxAny([3, 1, 9]);       // int    ✅
final latest = maxAny(['a', 'z']);       // String ✅

// ✅ no bound at all — the caller brings the ordering
T maxBy<T>(List<T> xs, Comparator<T> compare) =>
    xs.reduce((a, b) => compare(a, b) >= 0 ? a : b);

final newest = maxBy(orders, (a, b) => a.placedAt.compareTo(b.placedAt));

