import 'dart:async';

// ❌ the arms overlap: Object includes Future<String>
FutureOr<Object> payload() => Future<String>.value('data');

Future<void> ambiguous() async {
  final v = await payload();
  print(v.runtimeType);      // String — the Future you meant as data is gone
  print(payload() is Future); // true, and it tells you nothing useful
}

// FutureOr<Object?> carries no information at all — it IS Object?
void degenerate() {
  print(<FutureOr<Object?>>[] is List<Object?>);   // true
  print(<Object?>[] is List<FutureOr<Object?>>);   // true
}

// ✅ a concrete T that cannot be a future — narrowing is exact
FutureOr<int> count() => 7;

Future<void> narrow() async {
  final v = count();
  if (v is Future<int>) {
    print(await v);
  } else {
    print(v + 1);            // promoted to int, no microtask spent
  }
}

// ❌ no bound can exclude Future, so a caller can break this for you
class Slot<T> {
  FutureOr<T> value;         // Slot<Future<int>> makes `value` un-narrowable
  Slot(this.value);
}

// ✅ a tagged union: the arms are different classes, not a runtime guess
sealed class Cell<T> {}

class Value<T> extends Cell<T> {
  final T value;
  Value(this.value);
}

class Deferred<T> extends Cell<T> {
  final Future<T> future;
  Deferred(this.future);
}

Future<T> resolve<T>(Cell<T> cell) async => switch (cell) {
      Value(:final value) => value,
      Deferred(:final future) => await future,
    };

class Animal {
  String get name => 'animal';
}

class Dog extends Animal {
  void fetch() {}
}

typedef DogHandler = void Function(Dog dog);

void callWith(DogHandler h) => h(Dog());

void logAnything(Object o) => print(o);
void walkAnimal(Animal a) => print(a.name);
void walkDog(Dog d) => d.fetch();

T identity<T>(T v) => v;

void ping([int code = 0]) {}

void main() {
  // ✅ parameters are contravariant — a wider parameter is always safe
  callWith(logAnything);
  callWith(walkAnimal);
  callWith(walkDog);

  // ❌ the slot may be called with any Animal, so a Dog handler cannot fill it
  // final void Function(Animal) h = walkDog;
  //   'void Function(Dog)' can't be assigned to 'void Function(Animal)'

  // ✅ returns are covariant
  final Animal Function() make = () => Dog();
  print(make().name);

  // ✅ void is a top type — the returned value is simply discarded
  final void Function() tick = () => 42;
  tick();

  // ✅ optional parameters fit both call shapes
  final void Function() a = ping;
  final void Function(int) b = ping;
  a();
  b(1);

  // ✅ implicit instantiation picks identity<int> from the context type
  final int Function(int) intId = identity;
  print(intId(3));

  // Variance composes through type arguments
  print(<void Function(Object)>[] is List<void Function(Dog)>);   // true
  print(walkDog is void Function(Animal));                        // false
}

