// ❌ `_amount` would promote here too — if Invoice did not exist below
class Payment {
  final int? _amount;
  Payment(this._amount);

  void charge() {
    // if (_amount != null) print(_amount.isEven);
    //   '_amount' couldn't be promoted because there is a conflicting
    //   non-promotable field in class 'Invoice'
    final amount = _amount;      // ✅ a final local always works
    if (amount != null) print(amount.isEven);
  }
}

class Invoice {
  int? _amount;                  // non-final, same private name: the whole bug
  Invoice(this._amount);
  void clear() => _amount = null;
}

class Uploader {
  // ❌ the closure below demotes `path` from the moment it is created
  void bad(String? path, void Function(void Function()) later) {
    later(() => path = null);
    // if (path != null) print(path.length);   // ❌ no promotion here
  }

  // ✅ order matters — the check precedes the closure
  void ok(String? path, void Function(void Function()) later) {
    if (path != null) print(path.length);
    later(() => path = null);
  }

  // ✅ a final local cannot be written, so nothing can take the promotion away
  void best(String? path) {
    final p = path;
    if (p == null) return;
    print(p.length);
    Future(() => print(p.length));    // reading in a closure is fine
  }
}

extension type UserId(String value) {
  bool get isValid => value.isNotEmpty;
  // String toString() => ...;   // ❌ compile error: conflicts with Object
}

// `implements` exposes the representation's members and widens assignability
extension type OrderId(String value) implements String {}

void statics(UserId id) {
  print(id.isValid);
  // takesString(id);          // ❌ UserId is not a subtype of String
  print(OrderId('o-1').toUpperCase());   // ✅ O-1, via implements String
}

void takesString(String s) {}

void main() {
  final id = UserId('u-1');

  // The wrapper does not exist at run time
  print(id.runtimeType);            // String
  print('anything' is UserId);      // true
  final smuggled = 'raw' as UserId; // succeeds — no check to fail
  print(smuggled.isValid);

  // Reified type arguments are erased too
  print(<UserId>[id] is List<String>);              // true
  print((<String>['a'] as List<UserId>).length);    // 1

  // Equality is the representation's equality
  print(id == 'u-1');               // true

  // Members are resolved statically — dynamic dispatch finds nothing
  final dynamic d = id;
  try {
    d.isValid;
  } on NoSuchMethodError {
    print('no such member on a String');
  }

  // A type pattern matches every String, not just the ids you made
  switch ('not an id' as Object?) {
    case UserId u:
      print('matched: ${u.value}');   // this branch runs
    default:
      print('never reached');
  }
}

import 'dart:convert';

class Animal {}

class Dog extends Animal {}

void exactness() {
  final Animal a = Dog();
  print(a.runtimeType);              // Dog — the exact class, not the static type
  print(a.runtimeType == Animal);    // false — a registry keyed on Animal misses

  print(<String>[].runtimeType == List<String>);    // true
  print(<String>[].runtimeType == List<dynamic>);   // false

  // Private implementation classes you cannot name as a key
  print(jsonDecode('{"a":1}').runtimeType);   // _Map<String, dynamic>
  print(jsonDecode('[1]').runtimeType);       // List<dynamic>
}

// ❌ exact-match dispatch: every subclass falls through to the default
final registry = <Type, String Function(Object)>{
  Animal: (a) => 'an animal',
};
String describeBad(Object v) =>
    (registry[v.runtimeType] ?? (_) => 'unknown')(v);

