// ❌ unbounded: Cache<String, int?> makes `V?` ambiguous and `is V` unpromotable
class LooseCache<K, V> {
  final _m = <K, V>{};
  V? get(K key) => _m[key];   // null means "absent" — or "stored null"?
}

// ✅ bounded: nullable arguments are simply not expressible
class Cache<K extends Object, V extends Object> {
  final _m = <K, V>{};

  V? get(K key) => _m[key];   // null now means exactly "absent"
  void put(K key, V value) => _m[key] = value;

  // Read-only in, unmodifiable out
  void putAll(Iterable<MapEntry<K, V>> entries) => _m.addEntries(entries);
  Map<K, V> get snapshot => Map.unmodifiable(_m);
}

// ✅ a factory, because you cannot write `T()` from a type parameter
class Decoder<T extends Object> {
  final T Function(Map<String, dynamic> json) fromJson;
  const Decoder(this.fromJson);

  List<T> decodeList(List<Object?> raw) => [
        for (final row in raw) fromJson(row as Map<String, dynamic>),
      ];
}

sealed class Result<T, E> {}

class Ok<T, E> extends Result<T, E> {
  final T value;
  Ok(this.value);
}

class Err<T, E> extends Result<T, E> {
  final E error;
  Err(this.error);
}

// Never as a sentinel: this one cannot fail, and still fits anywhere
Result<int, Never> alwaysOk() => Ok(1);

void useNever() {
  final Result<int, String> r = alwaysOk();   // ✅ Never is the bottom type
  const List<String> empty = <Never>[];       // ✅ a valid empty List<String>
  print('$r $empty');
}

// ❌ dynamic at the boundary disables checking and spreads
void configureBad(dynamic options) => options.whateverYouLike();

// ✅ Object? makes the caller say what it is
void configure(Object? options) {
  if (options is Map<String, Object?>) print(options.length);
}
